// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testRegression_property() public {
        // Set MinSum to 10
        c.SetMinSum(10);
        // Initialize the contract
        c.Initialized();
        // Set up account with initial balance 0 and give it 10 wei
        address alice = address(0x1234);
        vm.deal(alice, 10 wei);
        // alice deposits 10 wei
        vm.prank(alice);
        c.Deposit{value: 10 wei}();
        // alice tries to Collect 10 wei
        bool ok;
        vm.prank(alice);
        try c.Collect(10) {
            ok = true;
        } catch {
            ok = false;
        }
        // In reference, Collect should revert because balances[alice] >= MinSum is true (10 >= 10)
        // but the check balances[msg.sender] >= MinSum && balances[msg.sender] >= _am passes, so it actually succeeds
        // Wait: Re-analyze: The reference has both conditions: balances[msg.sender] >= MinSum && balances[msg.sender] >= _am
        // With MinSum=10, balances[alice]=10, _am=10: 10>=10 and 10>=10 => true => Collect succeeds.
        // The bug removes the MinSum check, so only 10>=10 => true => Collect also succeeds.
        // They behave the same here. Need a case where reference fails and bug succeeds?
        // Actually, the bug condition is now: if(balances[msg.sender]>=_am) without the MinSum gate.
        // If MinSum is high (e.g., 20) and balance is 10, _am=10: reference fails (10<20), bug succeeds (10>=10).
        // Let's redo: Set MinSum=20, deposit 10, try Collect(10). Reference reverts, bug succeeds.
        // Re-deploy for clarity:
        c = new C();
        c.SetMinSum(20);
        c.Initialized();
        vm.deal(alice, 10 wei);
        vm.prank(alice);
        c.Deposit{value: 10 wei}();
        vm.prank(alice);
        try c.Collect(10) {
            ok = true;
        } catch {
            ok = false;
        }
        // For the reference, balances[alice] remains 10 (revert). For the bug, balances[alice] becomes 0 (success).
        // But we only have ONE deployed C instance. We cannot compare two versions in one test.
        // We need to assert a fact that holds for reference but fails for bug. Since the test runs only one contract (the one deployed from setUp), we must assume the test is run twice: once against reference C, once against mutated C. The assertion must be such that on reference it's true, on mutant it's false.
        // So we set up MinSum=20, deposit 10, call Collect(10). For reference: reverts => ok=false. For mutant: succeeds => ok=true.
        // So assertTrue(!ok) would be true on reference, false on mutant.
        // But we must read from c's public surface: we can check balances after the try/catch.
        // Actually we can just assertTrue(ok == false) because on reference it's false, on mutant it's true.
        assertTrue(ok == false);
    }
}

