pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testRegression_property() public {
        // Setup: initialize, set MinSum = 10, deposit 15 wei from address(1)
        c.SetMinSum(10);
        c.Initialized();
        address depositor = address(1);
        vm.deal(depositor, 15);
        vm.prank(depositor);
        c.Deposit{value: 15}();

        // Now a different caller (address(2)) tries Collect(5)
        address attacker = address(2);
        // The reference checks balances[msg.sender] >= MinSum, but attacker has balance 0, so Collect reverts
        // The bug only checks balances[msg.sender] >= _am (0 >= 5 false), so also reverts but differently
        // Actually we need a case where the reference reverts and the bug succeeds, causing balance difference
        // Let's instead have the depositor's balance >= MinSum (15 >= 10) and >= _am (15 >= 5)
        // But in the reference, the check is balances[msg.sender] >= MinSum && balances[msg.sender] >= _am
        // So depositor would succeed in both. We need a case where the first condition fails for the caller
        // but second condition passes – that requires balances[caller] >= _am but < MinSum
        // Let's give attacker some balance (4 wei) and make _am = 4, MinSum = 10
        // But attacker cannot call Deposit without Ether – we can send Ether via vm.deal and then call receive()?
        // Simpler: use vm.deal to give attacker balance directly, but that's not through deposit
        // Actually we can vm.deal(attacker, 4) then have attacker call Collect(4)
        vm.deal(attacker, 4);
        // But we need the balance reflected in balances[attacker] – it's not, only through Deposit().
        // So this doesn't work. Let's change scenario:
        // We'll have two depositors: address(1) deposits 15, address(2) deposits 5
        // Then address(2) calls Collect(5) – reference checks 5 >= 10 (MinSum) false => revert
        // Bug checks 5 >= 5 true => success, transferring 5 to address(2) and setting its balance to 0
        // While address(1) remains unchanged. 
        vm.deal(address(2), 5);
        vm.prank(address(2));
        c.Deposit{value: 5}();

        // Now address(2) calls Collect(5)
        bool ok;
        vm.prank(address(2));
        try c.Collect(5) {
            ok = true;
        } catch {
            ok = false;
        }
        // In reference, Collect reverts => ok = false, so c.balances(address(2)) stays 5
        // In bug, Collect succeeds => ok = true, so c.balances(address(2)) becomes 0
        // Assert that in reference the balance after call is still 5 (but we don't know which contract we're testing)
        // We must assert on actual state – we cannot know if code is ref or bug in test
        // So we assert the divergence: for this exact sequence, if ok is true then balance is 0, if false then 5
        // But the assertion must be true for reference and false for bug.
        // Reference: ok = false, balance = 5
        // Bug: ok = true, balance = 0
        // So assertTrue( (ok && c.balances(address(2)) == 0) || (!ok && c.balances(address(2)) == 5) )
        // That's a tautology in each case. Need a single condition that flips.
        // Better: assertTrue( c.balances(address(2)) == 5 ) – this holds for reference (no change) but fails for bug (balance becomes 0)
        assertTrue(c.balances(address(2)) == 5);
    }
}

