pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testRegression_property() public {
        // Setup: create user1, deploy contract, set MinSum and initialize
        address user1 = address(0x1001);
        vm.deal(user1, 1000 wei);

        c.SetMinSum(100);
        c.SetLogFile(address(0)); // dummy log address, log calls will revert but not affect balance
        c.Initialized();

        // User1 deposits 100 wei
        vm.prank(user1);
        c.Deposit{value: 100}();

        // Now balances[user1] = 100, MinSum = 100
        // Reference: collect(100) passes (100 >= 100 && 100 >= 100) -> withdrawal succeeds
        // Buggy: collect(100) fails (100 >= 100 && 100 <= 100 -> passes! actually both conditions satisfy, BUT wait:
        // Actually the bug changes second condition to <=, so 100 <= 100 is TRUE, so buggy also passes? 
        // We need a case where reference passes and bug fails.
        // Let's try: user1 balance=100, MinSum=100, collect(50)
        // Reference: 100>=100 && 100>=50 => TRUE -> withdrawal succeeds, balances goes to 50
        // Buggy: 100>=100 && 100<=50 => FALSE (100<=50 false) -> withdrawal fails, balance stays 100
        // So after collect(50): reference balance=50, buggy balance=100 -> divergence!

        vm.prank(user1);
        c.Collect(50);

        uint256 refBalance = c.balances(user1);
        assertTrue(refBalance == 50); // On reference this is 50, on buggy it's 100
    }
}

