pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testRegression_property() public {
        // Set up: initialize the contract, set MinSum to 0, set a log file address
        // (must set a non-zero address to avoid revert in Log.AddMessage? Actually Log is a contract, but we can set to any address; the test will succeed as long as no revert from Log.
        // We'll use a dummy address; the Log contract doesn't revert on AddMessage.
        c.SetMinSum(0);
        c.SetLogFile(address(0xdead));
        c.Initialized();

        address user = address(0x1234);
        vm.deal(user, 1 wei);
        vm.prank(user);
        c.Deposit{value: 1 wei}();

        // Now user balance = 1, MinSum = 0, so Collect can be called with _am = 1
        vm.prank(user);
        c.Collect(1);

        // The reference contract: balances[user] = 0 after collect
        // The buggy contract: require(balances + msg.value < balances) is false for any positive deposit, so Collect reverts before any state change, leaving balance = 1
        // Actually we need to read the balance. In the reference, it's 0; in bug, it's 1.
        assertTrue(c.balances(user) == 0);
    }
}

