pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testRegression_property() public {
        // Deploy and initialize
        c.SetMinSum(1);
        c.SetLogFile(address(0));
        c.Initialized();

        // Fund user address(1) with type(uint256).max wei
        vm.deal(address(1), type(uint256).max);
        // First deposit: send type(uint256).max wei
        vm.prank(address(1));
        c.Deposit{value: type(uint256).max}();

        // Now user balance is type(uint256).max
        // Second deposit: send 1 wei, which overflows to 0 in reference, reverts in buggy
        vm.deal(address(1), 1);
        vm.prank(address(1));
        // We use try/catch to catch potential revert
        bool ok;
        try c.Deposit{value: 1}() {
            ok = true;
        } catch {
            ok = false;
        }

        // In reference contract, the deposit succeeds (balance becomes 0 after overflow)
        // and the Collect of 0 wei works; in buggy contract, the second deposit reverts
        // so Collect will fail because balance is still type(uint256).max (>=1) but we try Collect(0) which should succeed
        // Instead we assert on the ok flag of the second deposit itself.
        assertTrue(ok, "Second deposit should succeed in reference but revert in buggy");
    }
}

