// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testRegression_property() public {
        // Set MinSum to 1 and initialize
        c.SetMinSum(1);
        c.SetLogFile(address(0xdead));
        c.Initialized();

        // Alice deposits 1 ether, meeting MinSum
        address alice = address(0x1234);
        vm.deal(alice, 2 ether);
        vm.prank(alice);
        c.Deposit{value: 1 ether}();

        // Alice calls Collect(1) - should send 1 wei back to her and reduce balance
        vm.prank(alice);
        c.Collect(1);

        // In the reference contract, Alice's balance becomes 1 ether - 1 wei (since 1 wei was sent back)
        // Actually balances are in wei: deposit 1 ether = 10^18 wei, then Collect(1) should subtract 1 wei
        // In the bug, the call goes to address(0), so Alice's balance is still 1 ether (10^18 wei) because the subtraction happens but ether is lost
        // The key difference is that reference: balances[alice] = 10^18 - 1, bug: balances[alice] = 10^18 - 1 (same subtraction) but ether is sent to address(0) instead of alice
        // However the property statement says 'balances differ at some key' - the key is alice's balance after the call
        // Actually both subtract the same amount from balances, so the balance snapshot is identical. 
        // The real observable difference is that address(this).balance (contract balance) is different:
        // In reference: contract lost 1 wei (sent to alice), in bug: contract lost 1 wei (sent to address(0)) - both lose wei... 
        // The actual divergence is that in the reference, alice receives the ether, in bug she doesn't.
        // We can observe this via address(alice).balance after the call.
        uint256 aliceBalanceAfter = alice.balance;
        // Reference: alice receives 1 wei, so her balance = 2 ether - 1 ether (deposit) + 1 wei (refund) = 1 ether + 1 wei
        // Bug: alice receives nothing, so her balance = 1 ether (remaining)
        // So we assert that alice.balance > 1 ether (the bug would leave it exactly 1 ether)
        assertTrue(aliceBalanceAfter > 1 ether, "Alice should have received the 1 wei");
    }
}

